          "task": "قم بكتابة برنامج بلغة C# يجسد منطق (مفهوم Short-Circuiting)، مع إضافة التحقق من صحة المدخلات وطباعة رسائل توضيحية تدل على اكتمال المعالجة بنجاح.",
